`default_nettype none
module bdc_ipow_top (input wire pin_in, output wire pin_out);

    wire rst = pin_in;

    // A free-running spine: the pipe acknowledges itself, so nothing settles
    // and its 69 latch bits keep changing.  Its latches are keep'd LUT
    // feedback loops and so are opaque to constant folding, which is the only
    // reason the datapath below survives synthesis.
    wire        p_ack_in, p_req_out;
    wire [68:0] spine_q;
    wire        spine;
    bd_delay #(.N(3)) uspin (.a(p_ack_in), .z(spine));

    bd_pipe #(.W(69), .N(4), .SDELAY(`BD_SZ_UPIPE_SDELAY),
              .DACK(`BD_SZ_UPIPE_UACK)) upipe (
        .rst(rst),
        .req_in(~spine), .ack_in(p_ack_in),
        .data_in({68'hc5a3c5a3c5a3c5a3c, pin_in}),
        .req_out(p_req_out), .ack_out(p_req_out), .data_out(spine_q));

    wire b_ack;
    wire e_ack;
    wire start_ack;
    wire out0_req;
    wire [31:0] out0_data;
    wire p_end_req;

    bdc_ipow #(
        .DELAY_UCMPI0(`BD_SZ_UUT_UCMPI0),
        .DELAY_UMUX0(`BD_SZ_UUT_UMUX0),
        .DELAY_UMUX1(`BD_SZ_UUT_UMUX1),
        .DELAY_UMUX2(`BD_SZ_UUT_UMUX2),
        .DELAY_UCONTROL_MERGE0(`BD_SZ_UUT_UCONTROL_MERGE0),
        .DELAY_USELECT0(`BD_SZ_UUT_USELECT0),
        .DELAY_UMULI1(`BD_SZ_UUT_UMULI1),
        .DELAY_USHRSI0(`BD_SZ_UUT_USHRSI0),
        .DELAY_UCMPI2(`BD_SZ_UUT_UCMPI2),
        .DELAY_UMUX3(`BD_SZ_UUT_UMUX3),
        .DELAY_UCONTROL_MERGE1(`BD_SZ_UUT_UCONTROL_MERGE1),
        .DELAY_ULINK_N1__1(`BD_SZ_UUT_ULINK_N1__1),
        .DELAY_ULINK_N1__1_UACK(`BD_SZ_UUT_ULINK_N1__1_UACK),
        .DELAY_ULINK_N10__0(`BD_SZ_UUT_ULINK_N10__0),
        .DELAY_ULINK_N10__0_UACK(`BD_SZ_UUT_ULINK_N10__0_UACK),
        .DELAY_ULINK_N10__1(`BD_SZ_UUT_ULINK_N10__1),
        .DELAY_ULINK_N10__1_UACK(`BD_SZ_UUT_ULINK_N10__1_UACK),
        .DELAY_ULINK_N10__2(`BD_SZ_UUT_ULINK_N10__2),
        .DELAY_ULINK_N10__2_UACK(`BD_SZ_UUT_ULINK_N10__2_UACK),
        .DELAY_ULINK_N10__2_SDELAY(`BD_SZ_UUT_ULINK_N10__2_SDELAY),
        .DELAY_ULINK_N12__1(`BD_SZ_UUT_ULINK_N12__1),
        .DELAY_ULINK_N12__1_UACK(`BD_SZ_UUT_ULINK_N12__1_UACK),
        .DELAY_ULINK_N13(`BD_SZ_UUT_ULINK_N13),
        .DELAY_ULINK_N13_UACK(`BD_SZ_UUT_ULINK_N13_UACK),
        .DELAY_ULINK_N13_SDELAY(`BD_SZ_UUT_ULINK_N13_SDELAY),
        .DELAY_ULINK_N15(`BD_SZ_UUT_ULINK_N15),
        .DELAY_ULINK_N15_UACK(`BD_SZ_UUT_ULINK_N15_UACK),
        .DELAY_ULINK_N17__0(`BD_SZ_UUT_ULINK_N17__0),
        .DELAY_ULINK_N17__0_UACK(`BD_SZ_UUT_ULINK_N17__0_UACK),
        .DELAY_ULINK_N17__0_SDELAY(`BD_SZ_UUT_ULINK_N17__0_SDELAY),
        .DELAY_ULINK_N17__1(`BD_SZ_UUT_ULINK_N17__1),
        .DELAY_ULINK_N17__1_UACK(`BD_SZ_UUT_ULINK_N17__1_UACK),
        .DELAY_ULINK_N17__2(`BD_SZ_UUT_ULINK_N17__2),
